-- Stage 9: feeder thresholds and the existing global notification singleton only.
ALTER TABLE public.notification_config ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL;
CREATE OR REPLACE FUNCTION public.save_feeder_threshold(p_id uuid,p_feeder_id uuid,p_parameter_code text,p_min numeric,p_max numeric,p_reason text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF public.get_my_role() NOT IN ('FIELD_OFFICER'::public.app_user_role,'ADMIN'::public.app_user_role,'SUPER_ADMIN'::public.app_user_role) OR NOT EXISTS(SELECT 1 FROM public.get_my_manageable_feeder_station_ids() s JOIN public.feeders f ON f.station_id=s.station_id WHERE f.id=p_feeder_id AND f.active) THEN RAISE EXCEPTION 'Threshold is outside your permitted scope' USING ERRCODE='42501'; END IF; IF p_min IS NULL AND p_max IS NULL OR p_min IS NOT NULL AND p_max IS NOT NULL AND p_min>p_max THEN RAISE EXCEPTION 'Provide a valid minimum and/or maximum threshold' USING ERRCODE='22023'; END IF; INSERT INTO public.feeder_thresholds(id,feeder_id,parameter_code,min_value,max_value) VALUES(coalesce(p_id,gen_random_uuid()),p_feeder_id,p_parameter_code,p_min,p_max) ON CONFLICT(feeder_id,parameter_code) DO UPDATE SET min_value=excluded.min_value,max_value=excluded.max_value,updated_at=now() RETURNING id INTO v_id; INSERT INTO public.administration_audit_log(actor_id,action,entity_type,entity_id,after_data,reason) VALUES(auth.uid(),'SAVE','FEEDER_THRESHOLD',v_id,jsonb_build_object('feeder_id',p_feeder_id,'parameter_code',p_parameter_code,'min',p_min,'max',p_max),nullif(btrim(coalesce(p_reason,'')),'')); RETURN v_id; END; $$;
CREATE OR REPLACE FUNCTION public.update_global_notification_config(p_id uuid,p_active boolean,p_max_unit_type text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.get_my_role() NOT IN ('ADMIN'::public.app_user_role,'SUPER_ADMIN'::public.app_user_role) THEN RAISE EXCEPTION 'Only Admin or Super Admin may update global notification settings' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.get_org_unit_types() t WHERE t.unit_type=p_max_unit_type) THEN RAISE EXCEPTION 'Unsupported organisational boundary' USING ERRCODE='22023'; END IF; IF btrim(coalesce(p_reason,''))='' THEN RAISE EXCEPTION 'A confirmation reason is required' USING ERRCODE='22023'; END IF; UPDATE public.notification_config SET active=p_active,max_unit_type=p_max_unit_type,updated_at=now(),updated_by=auth.uid() WHERE id=p_id; IF NOT FOUND THEN RAISE EXCEPTION 'Notification configuration not found' USING ERRCODE='P0002'; END IF; INSERT INTO public.administration_audit_log(actor_id,action,entity_type,entity_id,after_data,reason) VALUES(auth.uid(),'UPDATE','GLOBAL_NOTIFICATION_CONFIG',p_id,jsonb_build_object('active',p_active,'max_unit_type',p_max_unit_type),p_reason); END; $$;
GRANT EXECUTE ON FUNCTION public.save_feeder_threshold(uuid,uuid,text,numeric,numeric,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_global_notification_config(uuid,boolean,text,text) TO authenticated;
